def _xml_to_dict(xml):
    """
    Helper function to covert xml into a data dictionary.

    xml
        The xml data to convert.
    """
    if not xml:
        return None
    root = ET.fromstring(xml)
    data = {}
    for child in root:
        if child.tag in data:
            if type(data[child.tag]) is list:
                data[child.tag].append(_xml_to_dict(ET.tostring(child)))
            else:
                data[child.tag] = [data[child.tag], _xml_to_dict(ET.tostring(child))]
        else:
            data[child.tag] = _xml_to_dict(ET.tostring(child))
    return data

