def _dict_to_xml(data):
    """
    Helper function to convert a data dictionary into xml.

    data
        The data dictionary to convert.
    """
    if not data:
        return None
    xml = "<xml>"
    for key in data:
        if type(data[key]) is list:
            for value in data[key]:
                xml += "<{0}>{1}</{0}>".format(key, value)
        else:
            xml += "<{0}>{1}</{0}>".format(key, data[key])
    xml += "</xml>"
    return xml


def _get_id_from_xml(xml):
    """
    Helper function to extract the id from an xml response.

    xml
        The xml data to extract the id from.
    """
    if not xml:
        return None
    root = ET.fromstring(xml)
    return root.attrib["id"]


